import * as T from '../../aft/tactics/vendor/three.module.js';
import {createColdwellArt} from './index.js';
const $=id=>document.getElementById(id),canvas=document.querySelector('canvas'),stage=document.querySelector('.stage'),abort=new AbortController(),signal=abort.signal;
const revision=new URL(location.href).searchParams.get('revision')||'working tree';$('revision').textContent='Art source · '+revision;
const common={rect:{x:120,y:72,w:72,h:72},heightBands:[{min:44.3,max:50}],cutaway:{display:false,canopies:false}},views={
 approach:{title:'Above-ground approach',description:'Original trees, dirt approach and open gate; one 72 × 72 m render window.',focus:[104.5,47.2,190.5],span:28,region:{rect:{x:72,y:168,w:72,h:72},heightBands:[{min:46.4,max:56}]}},
 interior:{title:'Gatehouse interior',description:'Original 1 m doorway and windows; support roof at 48.76 m hidden for inspection.',focus:[94,47.2,140],span:13,region:{rect:{x:72,y:120,w:72,h:72},heightBands:[{min:46.4,max:49}],cutaway:{roofs:false,canopies:false,display:false}}},
 portal:{title:'Original entrance portal',description:'The companion access anchor and authored stair opening retain their exact placement and height.',focus:[73.5,44.8,115.5],span:20,region:{rect:{x:48,y:96,w:72,h:72},heightBands:[{min:40.15,max:49.5}],cutaway:{roofs:false,canopies:false,display:false,plane:{normal:[0,0,-1],constant:117}}}},
 b5:{title:'B5 · curved floor and openings',description:'96-sided source curvature, clipped floor cells, central opening and original bridge. Only nearby floor bands are allocated.',focus:[149.5,36.8,103.5],span:23,region:{rect:{x:120,y:72,w:72,h:72},heightBands:[{min:33.8,max:38.2}],cutaway:{roofs:false,display:false,plane:{normal:[0,0,-1],constant:103.5}}}},
 stairs:{title:'B5 stair connection',description:'Exact source treads, intermediate landing and 2.12 m rise. The artist adapter supplies no movement rules.',focus:[149.5,35.7,109.2],span:11,region:{rect:{x:120,y:96,w:72,h:72},heightBands:[{min:33.8,max:38.2}],cutaway:{roofs:false,display:false,plane:{normal:[0,0,-1],constant:110.8}}}},
 closed:{title:'Silo cover · closed',description:'Original cover rig at source pose 0. No internal animation or clock.',focus:[149.5,47.2,103.5],span:28,region:common,cover:0},
 half:{title:'Silo cover · halfway',description:'Original cover rig at source pose 0.5; half of its authored 12 m travel.',focus:[153,47.2,103.5],span:28,region:common,cover:.5},
 open:{title:'Silo cover · open',description:'Original cover rig at source pose 1; the opening and clipped surface infill remain clear.',focus:[155,47.2,103.5],span:30,region:common,cover:1}
};
let art,renderer,camera,scene,selected='approach',az=.72,el=.78,span=28,focus=new T.Vector3(),drag=null,webglError='',disposed=false;
function report(extra={}){const d=art?.diagnostics();$('diagnostics').textContent=JSON.stringify({sourceRevision:revision,webgl:renderer?'native':'unavailable',...extra,...(d?{residentEntries:d.residentEntries,candidateDrawObjects:d.drawObjects,candidateTriangles:d.triangles,geometryBytes:d.geometryBytes,instanceBytes:d.instanceBytes,texturePixels:d.texturePixels,poses:d.poses,counters:d.counters}:{}),...(renderer?{renderer:renderer.info.render,memory:renderer.info.memory}:{} )},null,2);}
function render(){if(disposed||!renderer)return;const w=stage.clientWidth,h=stage.clientHeight,aspect=w/h;renderer.setSize(w,h,false);camera.left=-span*aspect/2;camera.right=span*aspect/2;camera.top=span/2;camera.bottom=-span/2;camera.position.copy(focus).add(new T.Vector3(Math.cos(az)*Math.cos(el),Math.sin(el),Math.sin(az)*Math.cos(el)).multiplyScalar(200));camera.lookAt(focus);camera.updateProjectionMatrix();camera.updateMatrixWorld(true);renderer.render(scene,camera);report();}
async function show(id){if(disposed)return;const view=views[id];$('render-status').textContent='Loading '+view.title+'…';const region=structuredClone(view.region);$('roofs').checked=region.cutaway?.roofs!==false;$('canopies').checked=region.cutaway?.canopies!==false;art.syncDynamicState({'silo-cover':view.cover??1,...Object.fromEntries([5,8,11,14,17,20].map(n=>['service-bridge-'+n,1]))});const result=await art.setVisibleRegion(region);if(!result.applied||disposed)return;selected=id;span=view.span;focus.fromArray(view.focus);$('view-title').textContent=view.title;$('view-description').textContent=view.description;for(const b of document.querySelectorAll('[data-view]'))b.setAttribute('aria-current',String(b.dataset.view===id));$('render-status').textContent=renderer?'Native WebGL · verified assets · bounded geometry':'Native WebGL unavailable · geometry loaded and checked; visual approval pending';document.body.dataset.ready=renderer?'native-ready':'geometry-ready-webgl-unavailable';render();report({view:id,visualApproval:renderer?'requires inspection':'blocked: '+webglError});}
try{
 const context=canvas.getContext('webgl2',{antialias:true,alpha:false,preserveDrawingBuffer:true});if(context){renderer=new T.WebGLRenderer({canvas,context,antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(1);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;renderer.localClippingEnabled=true;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;scene=new T.Scene();scene.background=new T.Color(0x273a31);camera=new T.OrthographicCamera(-10,10,10,-10,.1,600);scene.add(new T.HemisphereLight(0xfff2d4,0x45594c,2));const sun=new T.DirectionalLight(0xffe4b0,2.3);sun.position.set(110,90,130);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-90,right:90,top:90,bottom:-90,near:1,far:250});sun.target.position.set(120,25,110);scene.add(sun,sun.target);}else webglError='The browser returned no WebGL 2 context.';
 art=await createColdwellArt({THREE:T});if(scene)scene.add(art.root);await show('approach');
 for(const b of document.querySelectorAll('[data-view]'))b.addEventListener('click',()=>show(b.dataset.view).catch(fail),{signal});
 for(const id of ['roofs','canopies'])$(id).addEventListener('change',()=>{const region=structuredClone(views[selected].region);region.cutaway={...region.cutaway,roofs:$('roofs').checked,canopies:$('canopies').checked};art.setVisibleRegion(region).then(()=>{render();report();}).catch(fail);},{signal});
 $('doors').addEventListener('input',()=>{const value=Number($('doors').value);$('door-value').textContent=value+'°';art.syncDynamicState(Object.fromEntries(['west','east','inner','portal'].map(id=>['blast-door-'+id,value])));render();report();},{signal});
 $('unload').addEventListener('click',()=>art.setVisibleRegion({rect:{x:0,y:0,w:24,h:24},heightBands:[{min:-100,max:-90}]}).then(()=>{render();report({unloaded:true});}).catch(fail),{signal});$('restore').addEventListener('click',()=>show(selected).catch(fail),{signal});
 $('dispose').addEventListener('click',async()=>{await art.dispose();report({disposed:true});$('render-status').textContent='Art disposed · geometry and owned textures released';for(const b of document.querySelectorAll('button,input'))b.disabled=true;renderer?.dispose();renderer?.forceContextLoss();disposed=true;},{signal});
 canvas.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId);},{signal});canvas.addEventListener('pointermove',e=>{if(!drag)return;az-=(e.clientX-drag[0])*.008;el=Math.max(.12,Math.min(1.5,el+(e.clientY-drag[1])*.008));drag=[e.clientX,e.clientY];render();},{signal});canvas.addEventListener('pointerup',()=>drag=null,{signal});canvas.addEventListener('wheel',e=>{e.preventDefault();span=Math.max(5,Math.min(100,span*Math.exp(e.deltaY*.001)));render();},{signal,passive:false});window.addEventListener('resize',render,{signal});
}catch(error){fail(error);}
function fail(error){$('errors').textContent=error.stack||error.message;document.body.dataset.ready='error';$('render-status').textContent='Coldwell proving view failed';}
window.addEventListener('pagehide',()=>{abort.abort();art?.dispose();renderer?.dispose();},{once:true});
